INSERT INTO "inspection_cases" ("id", "case_id", "tender_id", "tender_title", "supplier_id", "supplier_name", "batch_id", "batch_number", "asset_id", "serial_number", "model_number", "oem", "detected_issue", "expected_spec", "observed_spec", "inspector_id", "inspector_name", "inspection_date", "checklist", "evidence_photos", "officer_remarks", "final_decision", "decision_justification", "decided_at", "decided_by_name", "created_at", "updated_at") VALUES (1, 'INSP-CASE-2026-002', 7, 'Procurement of 20,000 Laptops for Government Educational & Administrative Institutions', 4, 'ABC Technologies Private Limited', 1, 'BATCH-2026-DEL-01', 'GEM-ASSET-LTP-002', 'SN-DELL-5530-MIS-02', 'Latitude 5530 FHD', 'Dell Technologies', 'Physical inspection ordered: Inspect M.2 drive bay part label and verify whether a 256 GB drive was delivered instead of contracted 512 GB part.', '{"cpu": "Intel Core i5 (12th Gen or equivalent)", "ram_gb": 16, "ram_display": "16 GB DDR4-3200", "ssd_gb": 512, "storage_display": "512 GB M.2 NVMe SSD", "display_inch": 15.6, "display_resolution": "1920x1080 FHD IPS", "os": "Windows 11 Pro", "warranty_years": 3, "warranty": "3 Years Comprehensive On-Site Next Business Day"}'::json, '{"cpu": "Intel Core i5-12400", "ram_gb": 16, "ssd_gb": 256, "display_inch": 15.6, "display_resolution": "1920x1080 FHD", "warranty_years": 3, "warranty": "3 Years On-site"}'::json, 1, 'Priya Nair (Procurement Officer)', '2026-09-15 19:24:44.461452', '[{"item": "CPU", "name": "CPU / Processor Grade", "status": "PASS", "expected": "Intel Core i5 (12th Gen or equivalent)", "observed": "Intel Core i5-12400", "notes": "Pre-filled from hardware readout", "is_ai_prefilled": true}, {"item": "RAM", "name": "System Memory (RAM Capacity & Frequency)", "status": "PASS", "expected": "16 GB", "observed": "16 GB", "notes": "RAM verified", "is_ai_prefilled": true}, {"item": "SSD", "name": "Primary Storage (SSD Capacity & NVMe Spec)", "status": "FAIL", "expected": "512 GB NVMe SSD", "observed": "256 GB NVMe SSD", "notes": "Drive capacity mismatch detected by scanner", "is_ai_prefilled": true}, {"item": "Display", "name": "Display Panel (Resolution & Panel Integrity)", "status": "PASS", "expected": "15.6\" FHD", "observed": "15.6\"", "notes": "Panel size verified", "is_ai_prefilled": true}, {"item": "Battery", "name": "Battery Health & Charge Cycle Verification", "status": "PASS", "expected": "As per contract", "observed": "Pending technician test", "notes": "Primary battery capacity 58Wh verified under 100% load.", "is_ai_prefilled": false}, {"item": "Keyboard", "name": "Keyboard & Touchpad Functional Test", "status": "PASS", "expected": "As per contract", "observed": "Pending technician test", "notes": "All 104 keys and precision touchpad operational.", "is_ai_prefilled": false}, {"item": "Ports", "name": "I/O Ports (USB, Type-C, HDMI, Audio Jack)", "status": "NOT_TESTED", "expected": "As per contract", "observed": "Pending technician test", "notes": "", "is_ai_prefilled": false}, {"item": "Wi-Fi", "name": "Wireless LAN & Bluetooth Connectivity", "status": "NOT_TESTED", "expected": "As per contract", "observed": "Pending technician test", "notes": "", "is_ai_prefilled": false}, {"item": "Webcam", "name": "Integrated Webcam & Microphone Array", "status": "NOT_TESTED", "expected": "As per contract", "observed": "Pending technician test", "notes": "", "is_ai_prefilled": false}, {"item": "Charger", "name": "OEM Power Adapter & Charging Circuitry", "status": "NOT_TESTED", "expected": "As per contract", "observed": "Pending technician test", "notes": "", "is_ai_prefilled": false}, {"item": "Physical condition", "name": "Chassis Casing, Hinges & Tamper Seal", "status": "NOT_TESTED", "expected": "As per contract", "observed": "Pending technician test", "notes": "", "is_ai_prefilled": false}, {"item": "Serial number", "name": "Chassis Barcode vs BIOS Serial Match", "status": "PASS", "expected": "Must match packing manifest", "observed": "Laser etched chassis barcode verified", "notes": "Matches registry", "is_ai_prefilled": true}, {"item": "Warranty", "name": "OEM Portal Warranty Entitlement SLA", "status": "PASS", "expected": "3 Years Comprehensive On-Site", "observed": "3 Years On-site", "notes": "", "is_ai_prefilled": true}]'::json, '[{"id": "photo_1", "title": "Chassis Underside & Serial Barcode", "url": "https://images.unsplash.com/photo-1588872657578-7efd1f1555ed?w=600&auto=format&fit=crop&q=60", "caption": "Chassis laser etching for SN: SN-DELL-5530-MIS-02"}, {"id": "photo_2", "title": "Internal M.2 NVMe Storage Drive Label", "url": "https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?w=600&auto=format&fit=crop&q=60", "caption": "M.2 SSD part sticker showing manufacturer capacity marking"}]'::json, 'Vendor given 48 hours to replace unit before batch rejection.', 'REQUEST_CLARIFICATION', 'Physical disassembly verified that an M.2 256 GB drive is installed instead of contracted 512 GB NVMe SSD. Formal clarification and show cause issued to ABC Technologies to replace with contracted parts.', '2026-09-15 19:37:11.360094', 'Priya Nair', '2026-09-15 19:24:44', '2026-09-15 19:37:11');
INSERT INTO "inspection_cases" ("id", "case_id", "tender_id", "tender_title", "supplier_id", "supplier_name", "batch_id", "batch_number", "asset_id", "serial_number", "model_number", "oem", "detected_issue", "expected_spec", "observed_spec", "inspector_id", "inspector_name", "inspection_date", "checklist", "evidence_photos", "officer_remarks", "final_decision", "decision_justification", "decided_at", "decided_by_name", "created_at", "updated_at") VALUES (2, 'INSP-CASE-001', 7, 'Procurement of 20,000 Laptops for Government Educational & Administrative Institutions', 12, 'ABC Technologies Private Limited', 2, 'BAT-2026-001', 'ASSET-2026-003', 'SN-DELL-882393', 'Latitude 3520 Gov Ed', 'Dell Technologies', 'Hardware Specification Mismatch: Installed SSD is 256 GB NVMe instead of tender required 512 GB NVMe.', '{"cpu": "Intel Core i5 or equivalent", "ram_gb": 16, "ssd_gb": 512, "display": "15.6 FHD", "os": "Windows 11 Pro", "warranty": "3 Years On-site"}'::json, '{"cpu": "Intel Core i5-1135G7", "ram_gb": 16, "ssd_gb": 256, "display": "15.6 FHD"}'::json, NULL, 'Er. Sanjeev Verma (Senior Technical Officer)', '2026-09-15 18:19:24.721642', '[{"name": "CPU", "status": "PASS", "notes": "Intel Core i5-1135G7 confirmed via BIOS and OS hardware monitor."}, {"name": "RAM", "status": "PASS", "notes": "16 GB DDR4 3200MHz module verified in slot 1."}, {"name": "SSD Storage", "status": "FAIL", "notes": "Observed Kioxia 256 GB NVMe SSD. Tender contract explicitly requires 512 GB."}, {"name": "Display Panel", "status": "PASS", "notes": "15.6 inch FHD (1920x1080) panel confirmed."}, {"name": "Battery", "status": "PASS", "notes": "54 Whr battery health 100%."}, {"name": "Keyboard & Trackpad", "status": "PASS", "notes": "All keys functioning, bilingual Hindi/English legend present."}, {"name": "Ports (USB, HDMI, LAN)", "status": "PASS", "notes": "All I/O ports tested and functioning."}, {"name": "Wi-Fi & Bluetooth", "status": "PASS", "notes": "Wi-Fi 6 AX201 and BT 5.1 connected."}, {"name": "Webcam & Mic", "status": "PASS", "notes": "720p HD webcam with physical privacy shutter."}, {"name": "Charger / Adapter", "status": "PASS", "notes": "65W Type-C adapter with BIS registration mark."}, {"name": "Physical Condition", "status": "PASS", "notes": "Brand new factory sealed chassis, no scratches."}, {"name": "Serial Number Verification", "status": "PASS", "notes": "Chassis laser etched serial matches BIOS and carton barcode."}, {"name": "Warranty Document", "status": "PASS", "notes": "Dell OEM 3-year ProSupport certificate attached."}]'::json, '[{"url": "/demo/photos/ssd_disassembly_256gb.jpg", "caption": "Disassembly photo showing 256GB M.2 drive"}, {"url": "/demo/photos/bios_storage_report.jpg", "caption": "BIOS screen reporting 256GB NVMe"}]'::json, 'Notice issued to OEM', 'REQUEST_CLARIFICATION', 'Mandatory testing of decision workflow in Phase 12', '2026-09-19 15:49:16.637273', 'Priya Nair', '2026-09-15 20:19:24', '2026-09-19 15:49:16');
