BEGIN;

-- Drop existing tables in reverse dependency order
DROP TABLE IF EXISTS "verification_results" CASCADE;
DROP TABLE IF EXISTS "documents" CASCADE;
DROP TABLE IF EXISTS "compliance_checks" CASCADE;
DROP TABLE IF EXISTS "product_assets" CASCADE;
DROP TABLE IF EXISTS "physical_inspection_requests" CASCADE;
DROP TABLE IF EXISTS "notifications" CASCADE;
DROP TABLE IF EXISTS "inspection_cases" CASCADE;
DROP TABLE IF EXISTS "bid_applications" CASCADE;
DROP TABLE IF EXISTS "audit_logs" CASCADE;
DROP TABLE IF EXISTS "users" CASCADE;
DROP TABLE IF EXISTS "tender_requirements" CASCADE;
DROP TABLE IF EXISTS "delivery_batches" CASCADE;
DROP TABLE IF EXISTS "vigilance_actions" CASCADE;
DROP TABLE IF EXISTS "tenders" CASCADE;
DROP TABLE IF EXISTS "bidders" CASCADE;

-- -------------------------------------------------------
-- Tables Definition
-- -------------------------------------------------------

CREATE TABLE bidders (
	id SERIAL NOT NULL, 
	legal_name VARCHAR(255) NOT NULL, 
	trade_name VARCHAR(255), 
	registered_address TEXT NOT NULL, 
	state VARCHAR(80) NOT NULL, 
	pincode VARCHAR(10) NOT NULL, 
	contact_email VARCHAR(255) NOT NULL, 
	contact_phone VARCHAR(20) NOT NULL, 
	director_name VARCHAR(255), 
	annual_turnover_inr NUMERIC(14, 2), 
	years_experience INTEGER, 
	udyam_number VARCHAR(32), 
	gstin VARCHAR(15), 
	pan VARCHAR(10), 
	cin VARCHAR(21), 
	nsic_registration VARCHAR(40), 
	dpiit_startup_number VARCHAR(40), 
	epfo_code VARCHAR(40), 
	esic_code VARCHAR(40), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_bidders_contact_email ON bidders (contact_email);
CREATE INDEX ix_bidders_contact_phone ON bidders (contact_phone);
CREATE INDEX ix_bidders_udyam_number ON bidders (udyam_number);
CREATE INDEX ix_bidders_pan ON bidders (pan);
CREATE INDEX ix_bidders_gstin ON bidders (gstin);

CREATE TABLE tenders (
	id SERIAL NOT NULL, 
	gem_bid_number VARCHAR(40) NOT NULL, 
	title VARCHAR(500) NOT NULL, 
	department VARCHAR(255) NOT NULL, 
	category VARCHAR(120) NOT NULL, 
	estimated_value_inr NUMERIC(14, 2) NOT NULL, 
	closing_date DATE NOT NULL, 
	description TEXT NOT NULL, 
	source_text TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE UNIQUE INDEX ix_tenders_gem_bid_number ON tenders (gem_bid_number);

CREATE TABLE vigilance_actions (
	id SERIAL NOT NULL, 
	alert_id VARCHAR(120) NOT NULL, 
	action VARCHAR(50) NOT NULL, 
	officer_id INTEGER, 
	officer_name VARCHAR(120), 
	reason TEXT, 
	notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id)
);

CREATE INDEX ix_vigilance_actions_alert_id ON vigilance_actions (alert_id);

CREATE TABLE delivery_batches (
	id SERIAL NOT NULL, 
	tender_id INTEGER NOT NULL, 
	awarded_bidder_id INTEGER NOT NULL, 
	batch_number VARCHAR(50) NOT NULL, 
	po_number VARCHAR(50) NOT NULL, 
	total_units INTEGER NOT NULL, 
	verified_units INTEGER NOT NULL, 
	failed_units INTEGER NOT NULL, 
	delivery_date TIMESTAMP WITH TIME ZONE, 
	delivery_location VARCHAR(255) NOT NULL, 
	status VARCHAR(80) NOT NULL, 
	notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tender_id) REFERENCES tenders (id), 
	FOREIGN KEY(awarded_bidder_id) REFERENCES bidders (id)
);

CREATE INDEX ix_delivery_batches_awarded_bidder_id ON delivery_batches (awarded_bidder_id);
CREATE UNIQUE INDEX ix_delivery_batches_batch_number ON delivery_batches (batch_number);
CREATE INDEX ix_delivery_batches_po_number ON delivery_batches (po_number);
CREATE INDEX ix_delivery_batches_tender_id ON delivery_batches (tender_id);

CREATE TABLE tender_requirements (
	id SERIAL NOT NULL, 
	tender_id INTEGER NOT NULL, 
	requirement VARCHAR(500) NOT NULL, 
	title VARCHAR(255), 
	description TEXT, 
	category VARCHAR(40) NOT NULL, 
	mandatory BOOLEAN NOT NULL, 
	required_value VARCHAR(255), 
	comparison_operator VARCHAR(50), 
	weight FLOAT, 
	threshold FLOAT, 
	currency VARCHAR(8), 
	evidence_types JSON, 
	notes TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tender_id) REFERENCES tenders (id)
);

CREATE INDEX ix_tender_requirements_category ON tender_requirements (category);
CREATE INDEX ix_tender_requirements_tender_id ON tender_requirements (tender_id);

CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR(255) NOT NULL, 
	hashed_password VARCHAR(255) NOT NULL, 
	full_name VARCHAR(255) NOT NULL, 
	role VARCHAR(40) NOT NULL, 
	is_active BOOLEAN NOT NULL, 
	bidder_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(bidder_id) REFERENCES bidders (id)
);

CREATE UNIQUE INDEX ix_users_email ON users (email);

CREATE TABLE audit_logs (
	id SERIAL NOT NULL, 
	sequence_number INTEGER, 
	actor_user_id INTEGER, 
	actor_role VARCHAR(60), 
	action VARCHAR(80) NOT NULL, 
	entity_type VARCHAR(80) NOT NULL, 
	entity_id INTEGER, 
	bid_id INTEGER, 
	result VARCHAR(40), 
	detail TEXT NOT NULL, 
	previous_value JSON, 
	new_value JSON, 
	reason TEXT, 
	extra JSON, 
	previous_event_hash VARCHAR(64), 
	event_hash VARCHAR(64), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(actor_user_id) REFERENCES users (id)
);

CREATE INDEX ix_audit_logs_event_hash ON audit_logs (event_hash);
CREATE INDEX ix_audit_logs_result ON audit_logs (result);
CREATE INDEX ix_audit_logs_bid_id ON audit_logs (bid_id);
CREATE INDEX ix_audit_logs_created_at ON audit_logs (created_at);
CREATE INDEX ix_audit_logs_sequence_number ON audit_logs (sequence_number);
CREATE INDEX ix_audit_logs_action ON audit_logs (action);
CREATE INDEX ix_audit_logs_actor_user_id ON audit_logs (actor_user_id);

CREATE TABLE bid_applications (
	id SERIAL NOT NULL, 
	reference_code VARCHAR(40) NOT NULL, 
	tender_id INTEGER NOT NULL, 
	bidder_id INTEGER NOT NULL, 
	status VARCHAR(40) NOT NULL, 
	verification_status VARCHAR(40) NOT NULL, 
	decision_notes TEXT, 
	override_reason TEXT, 
	decided_by_user_id INTEGER, 
	decided_at TIMESTAMP WITH TIME ZONE, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_bid_tender_bidder UNIQUE (tender_id, bidder_id), 
	FOREIGN KEY(tender_id) REFERENCES tenders (id), 
	FOREIGN KEY(bidder_id) REFERENCES bidders (id), 
	FOREIGN KEY(decided_by_user_id) REFERENCES users (id)
);

CREATE UNIQUE INDEX ix_bid_applications_reference_code ON bid_applications (reference_code);
CREATE INDEX ix_bid_applications_tender_id ON bid_applications (tender_id);
CREATE INDEX ix_bid_applications_bidder_id ON bid_applications (bidder_id);

CREATE TABLE inspection_cases (
	id SERIAL NOT NULL, 
	case_id VARCHAR(50) NOT NULL, 
	tender_id INTEGER NOT NULL, 
	tender_title VARCHAR(255) NOT NULL, 
	supplier_id INTEGER NOT NULL, 
	supplier_name VARCHAR(255) NOT NULL, 
	batch_id INTEGER NOT NULL, 
	batch_number VARCHAR(50) NOT NULL, 
	asset_id VARCHAR(50) NOT NULL, 
	serial_number VARCHAR(100) NOT NULL, 
	model_number VARCHAR(100) NOT NULL, 
	oem VARCHAR(100) NOT NULL, 
	detected_issue TEXT NOT NULL, 
	expected_spec JSON NOT NULL, 
	observed_spec JSON, 
	inspector_id INTEGER, 
	inspector_name VARCHAR(120) NOT NULL, 
	inspection_date TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	checklist JSON NOT NULL, 
	evidence_photos JSON, 
	officer_remarks TEXT, 
	final_decision VARCHAR(80) NOT NULL, 
	decision_justification TEXT, 
	decided_at TIMESTAMP WITH TIME ZONE, 
	decided_by_name VARCHAR(120), 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tender_id) REFERENCES tenders (id), 
	FOREIGN KEY(supplier_id) REFERENCES bidders (id), 
	FOREIGN KEY(batch_id) REFERENCES delivery_batches (id), 
	FOREIGN KEY(inspector_id) REFERENCES users (id)
);

CREATE INDEX ix_inspection_cases_supplier_id ON inspection_cases (supplier_id);
CREATE UNIQUE INDEX ix_inspection_cases_case_id ON inspection_cases (case_id);
CREATE INDEX ix_inspection_cases_batch_id ON inspection_cases (batch_id);
CREATE INDEX ix_inspection_cases_serial_number ON inspection_cases (serial_number);
CREATE INDEX ix_inspection_cases_tender_id ON inspection_cases (tender_id);
CREATE INDEX ix_inspection_cases_asset_id ON inspection_cases (asset_id);

CREATE TABLE notifications (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	title VARCHAR(255) NOT NULL, 
	body TEXT NOT NULL, 
	kind VARCHAR(40) NOT NULL, 
	bid_id INTEGER, 
	is_read BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_notifications_kind ON notifications (kind);
CREATE INDEX ix_notifications_user_id ON notifications (user_id);
CREATE INDEX ix_notifications_created_at ON notifications (created_at);

CREATE TABLE physical_inspection_requests (
	id SERIAL NOT NULL, 
	asset_id VARCHAR(50) NOT NULL, 
	serial_number VARCHAR(100) NOT NULL, 
	requested_by_user_id INTEGER NOT NULL, 
	requested_by_name VARCHAR(120) NOT NULL, 
	target_components JSON NOT NULL, 
	instructions TEXT NOT NULL, 
	status VARCHAR(80) NOT NULL, 
	findings TEXT, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(requested_by_user_id) REFERENCES users (id)
);

CREATE INDEX ix_physical_inspection_requests_asset_id ON physical_inspection_requests (asset_id);
CREATE INDEX ix_physical_inspection_requests_serial_number ON physical_inspection_requests (serial_number);

CREATE TABLE product_assets (
	id SERIAL NOT NULL, 
	batch_id INTEGER NOT NULL, 
	tender_id INTEGER NOT NULL, 
	asset_id VARCHAR(50) NOT NULL, 
	serial_number VARCHAR(100) NOT NULL, 
	qr_code_data TEXT NOT NULL, 
	model_number VARCHAR(100) NOT NULL, 
	oem VARCHAR(100) NOT NULL, 
	warranty VARCHAR(100) NOT NULL, 
	expected_spec JSON NOT NULL, 
	actual_spec JSON, 
	inspection_status VARCHAR(80) NOT NULL, 
	mismatch_details JSON, 
	inspection_notes TEXT, 
	verified_at TIMESTAMP WITH TIME ZONE, 
	verified_by_user_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(batch_id) REFERENCES delivery_batches (id), 
	FOREIGN KEY(tender_id) REFERENCES tenders (id), 
	FOREIGN KEY(verified_by_user_id) REFERENCES users (id)
);

CREATE UNIQUE INDEX ix_product_assets_serial_number ON product_assets (serial_number);
CREATE INDEX ix_product_assets_batch_id ON product_assets (batch_id);
CREATE INDEX ix_product_assets_tender_id ON product_assets (tender_id);
CREATE UNIQUE INDEX ix_product_assets_asset_id ON product_assets (asset_id);

CREATE TABLE compliance_checks (
	id SERIAL NOT NULL, 
	bidder_id INTEGER NOT NULL, 
	tender_id INTEGER NOT NULL, 
	bid_id INTEGER NOT NULL, 
	overall_score NUMERIC(5, 2) NOT NULL, 
	confidence NUMERIC(5, 2) NOT NULL, 
	risk_level VARCHAR(40) NOT NULL, 
	recommendation VARCHAR(40) NOT NULL, 
	summary TEXT NOT NULL, 
	score_breakdown JSON NOT NULL, 
	requirement_results JSON NOT NULL, 
	contradictions JSON NOT NULL, 
	risk_factors JSON NOT NULL, 
	related_bidders JSON NOT NULL, 
	findings JSON NOT NULL, 
	triggered_by_user_id INTEGER, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(bidder_id) REFERENCES bidders (id), 
	FOREIGN KEY(tender_id) REFERENCES tenders (id), 
	FOREIGN KEY(bid_id) REFERENCES bid_applications (id), 
	FOREIGN KEY(triggered_by_user_id) REFERENCES users (id)
);

CREATE INDEX ix_compliance_checks_bidder_id ON compliance_checks (bidder_id);
CREATE INDEX ix_compliance_checks_tender_id ON compliance_checks (tender_id);
CREATE INDEX ix_compliance_checks_bid_id ON compliance_checks (bid_id);

CREATE TABLE documents (
	id SERIAL NOT NULL, 
	bidder_id INTEGER NOT NULL, 
	bid_id INTEGER NOT NULL, 
	document_type VARCHAR(40) NOT NULL, 
	original_filename VARCHAR(255) NOT NULL, 
	stored_path VARCHAR(500) NOT NULL, 
	content_type VARCHAR(120) NOT NULL, 
	file_size_bytes INTEGER NOT NULL, 
	status VARCHAR(40) NOT NULL, 
	issued_name VARCHAR(255), 
	expiry_date DATE, 
	expiry_state VARCHAR(50) NOT NULL, 
	integrity_status VARCHAR(50) NOT NULL, 
	sha256_hash VARCHAR(64), 
	version INTEGER NOT NULL, 
	is_duplicate BOOLEAN NOT NULL, 
	duplicate_of_doc_id INTEGER, 
	validation_results JSON, 
	extracted_fields JSON, 
	uploaded_by_user_id INTEGER NOT NULL, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	updated_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(bidder_id) REFERENCES bidders (id), 
	FOREIGN KEY(bid_id) REFERENCES bid_applications (id), 
	FOREIGN KEY(uploaded_by_user_id) REFERENCES users (id)
);

CREATE INDEX ix_documents_bid_id ON documents (bid_id);
CREATE INDEX ix_documents_bidder_id ON documents (bidder_id);

CREATE TABLE verification_results (
	id SERIAL NOT NULL, 
	bid_id INTEGER NOT NULL, 
	document_id INTEGER, 
	check_key VARCHAR(80) NOT NULL, 
	source VARCHAR(80) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	simulated BOOLEAN NOT NULL, 
	summary TEXT NOT NULL, 
	payload JSON, 
	created_at TIMESTAMP WITH TIME ZONE DEFAULT now() NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(bid_id) REFERENCES bid_applications (id), 
	FOREIGN KEY(document_id) REFERENCES documents (id)
);

CREATE INDEX ix_verification_results_bid_id ON verification_results (bid_id);
CREATE INDEX ix_verification_results_check_key ON verification_results (check_key);


